async function refreshExecutions(){
 try{
  const rows=await api('/api/v1/executions'),root=$('#execution-list');root.replaceChildren();
  if(!rows.length){root.textContent='No executions yet. Run a published workflow to see its trace.';await refreshMetrics();return}
  rows.slice(0,12).forEach(row=>{const item=document.createElement('div');item.className='execution-row';const label=document.createElement('span'),project=savedRecords.find(record=>record.id===row.pipelineId);label.textContent=`${project?.definition.name||row.pipelineId} · ${row.workflow?workflowLabel(row.workflow)+' · ':''}v${row.pipelineVersion} · ${row.status}`;const actions=document.createElement('div');actions.className='execution-actions';const monitor=makeButton('Monitor','events','quiet');monitor.onclick=()=>openLiveMonitor(row.id);actions.append(monitor);const show=makeButton('Trace','view','quiet');show.onclick=()=>{openRunPanel();showExecution(row.id)};actions.append(show);if(['QUEUED','RUNNING'].includes(row.status)){const cancel=makeButton('Cancel','close','quiet danger');cancel.onclick=async()=>{cancel.disabled=true;try{await api(`/api/v1/executions/${encodeURIComponent(row.id)}/cancel`,{method:'POST'});await refreshExecutions();await showExecution(row.id)}catch(error){$('#execution-status').textContent=error.message}finally{cancel.disabled=false}};actions.append(cancel)}item.append(label,actions);root.append(item)});await refreshMetrics();
 }catch(error){$('#execution-status').textContent=error.message}
}
async function showExecution(id){
 try{
  $('#open-live-monitor').disabled=false;if(activeTraceId!==id){activeTraceId=id;lastEventSequence=0;$('#execution-events').replaceChildren()}
  const cursor=lastEventSequence,[snapshot,events]=await Promise.all([api(`/api/v1/executions/${encodeURIComponent(id)}`),api(`/api/v1/executions/${encodeURIComponent(id)}/events?afterSequence=${cursor}`)]);if(activeTraceId!==id)return;
  $('#trace-context').textContent=`${snapshot.workflow?workflowLabel(snapshot.workflow)+' · ':''}published v${snapshot.pipelineVersion} · ${snapshot.status}`;
  $('#execution-status').className=snapshot.status==='FAILED'?'execution-status error':'execution-status';
  $('#execution-status').textContent=`${snapshot.status}${snapshot.error?`: ${snapshot.error}`:''}${snapshot.output?` · ${JSON.stringify(snapshot.output)}`:''}`;
  const root=$('#execution-events');events.forEach(event=>{if(event.sequence<=lastEventSequence)return;const item=document.createElement('li');item.textContent=`${event.nodeId||'workflow'} · ${event.status} · ${event.message}${event.durationMillis?` (${event.durationMillis} ms)`:''}`;root.append(item);lastEventSequence=Math.max(lastEventSequence,event.sequence)});while(root.children.length>500)root.firstElementChild.remove();if($('#follow-execution').checked)root.scrollTop=root.scrollHeight;
 }catch(error){if(activeTraceId===id)$('#execution-status').textContent=error.message}
}
