function renderConnectionProviders(){const select=$('#connection-plugin'),previous=select.value;select.required=false;const label=select.closest('label');if(label)label.firstChild.textContent='Plugin settings to add';select.replaceChildren(new Option('Choose a plugin',''));plugins.filter(plugin=>plugin.capabilities?.includes('connection-preflight')&&Object.keys(plugin.configurationSchema?.properties||{}).length).forEach(plugin=>select.append(new Option(plugin.name,plugin.id)));if(previous)select.value=previous;let add=$('#connection-add-plugin');if(!add){add=document.createElement('button');add.id='connection-add-plugin';add.type='button';add.className='secondary';add.textContent='Add plugin settings';$('#connection-config').before(add);add.onclick=addConnectionPlugin}renderConnectionConfig()}
