function renderConnectionConfig(){const root=$('#connection-config');root.replaceChildren();root.className='provider-settings';for(const [pluginId,settings] of Object.entries(connectionDraft)){const plugin=plugins.find(item=>item.id===pluginId);if(!plugin)continue;const section=document.createElement('fieldset');section.className='connection-provider-settings';const legend=document.createElement('legend');legend.textContent=`${plugin.name} · v${settings.pluginVersion||plugin.version}`;const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Remove settings';remove.onclick=()=>{delete connectionDraft[pluginId];renderConnectionConfig()};section.append(legend,remove,createConfigForm({plugin,config:settings.config||(settings.config={})}));root.append(section)}if(!Object.keys(connectionDraft).length){const note=document.createElement('p');note.className='muted';note.textContent='Add one or more plugin settings to this profile.';root.append(note)}}
