function defaultCapabilities(){return{adapters:[],subscriptions:[],host:{type:'cli',port:8080,openBrowser:false},template:{id:'standard',version:'1',settings:{}}}}
function normalizeCapabilities(value){const defaults=defaultCapabilities();if(!value)return defaults;const copy=JSON.parse(JSON.stringify(value));return{...copy,adapters:Array.isArray(copy.adapters)?copy.adapters:[],subscriptions:(copy.subscriptions||[]).map(subscription=>({...subscription,nodeIds:subscription.nodeIds||[],eventTypes:subscription.eventTypes||[],severities:subscription.severities||[]})),host:{...defaults.host,...copy.host},template:{...defaults.template,...copy.template}}}
function adapterMetadata(type){return adapterCatalog.find(adapter=>adapter.type===type)}
function effectiveAdapters(workflow,nodeId){const ids=new Set(capabilities.subscriptions.filter(subscription=>subscription.workflow===workflow&&((subscription.nodeIds||[]).length===0||(subscription.nodeIds||[]).includes(nodeId))).map(subscription=>subscription.adapterId));return capabilities.adapters.filter(adapter=>ids.has(adapter.id))}
function workflowSubscription(adapterId,workflow){return capabilities.subscriptions.find(subscription=>subscription.adapterId===adapterId&&subscription.workflow===workflow&&!(subscription.nodeIds||[]).length)}
function changeNodeSubscription(adapterId,workflow,nodeId,enabled){
 if(enabled){if(!capabilities.subscriptions.some(subscription=>subscription.adapterId===adapterId&&subscription.workflow===workflow&&(subscription.nodeIds||[]).includes(nodeId)))capabilities.subscriptions.push({adapterId,workflow,nodeIds:[nodeId],eventTypes:[],severities:[]})}
 else capabilities.subscriptions=capabilities.subscriptions.flatMap(subscription=>{if(subscription.adapterId!==adapterId||subscription.workflow!==workflow||!(subscription.nodeIds||[]).includes(nodeId))return[subscription];const nodeIds=subscription.nodeIds.filter(id=>id!==nodeId);return nodeIds.length?[{...subscription,nodeIds}]:[]});
 markDirty();render();
}
function removeNodeSubscriptions(workflow,nodeId){capabilities.subscriptions=capabilities.subscriptions.flatMap(subscription=>{if(subscription.workflow!==workflow||!(subscription.nodeIds||[]).includes(nodeId))return[subscription];const nodeIds=subscription.nodeIds.filter(id=>id!==nodeId);return nodeIds.length?[{...subscription,nodeIds}]:[]})}
function changeWorkflowSubscription(adapterId,workflow,enabled){if(enabled&&!nodes.some(node=>node.workflow===workflow)){setCapabilityStatus('Add a processing node to this workflow before subscribing to it.','error');return}if(enabled&&!workflowSubscription(adapterId,workflow))capabilities.subscriptions.push({adapterId,workflow,nodeIds:[],eventTypes:[],severities:[]});if(!enabled)capabilities.subscriptions=capabilities.subscriptions.filter(subscription=>!(subscription.adapterId===adapterId&&subscription.workflow===workflow&&!(subscription.nodeIds||[]).length));markDirty();render();renderWorkflowSubscriptions()}
function filterField(subscription,key,labelText){const label=document.createElement('label');label.textContent=labelText;const input=document.createElement('input');input.value=(subscription[key]||[]).join(', ');input.placeholder=key==='severities'?'All severities':'All event types';input.onchange=()=>{subscription[key]=[...new Set(input.value.split(',').map(value=>value.trim().toUpperCase()).filter(Boolean))];markDirty()};label.append(input);return label}
function subscriptionFilters(subscription){const details=document.createElement('details');details.className='subscription-filters';const summary=document.createElement('summary');summary.textContent='Event filters';details.append(summary,filterField(subscription,'eventTypes','Event type codes, comma-separated'),filterField(subscription,'severities','Severities: TRACE, DEBUG, INFO, WARN, ERROR'));return details}
function createNodeAdapterSection(node){
 const section=document.createElement('details');section.className='inspector-section event-attachments';section.open=true;const summary=document.createElement('summary');summary.textContent='Event adapters';section.append(summary);
 const help=document.createElement('p');help.className='muted';help.textContent='Observe this node without changing processing edges.';section.append(help);
 for(const adapter of capabilities.adapters){const inherited=Boolean(workflowSubscription(adapter.id,node.workflow)),direct=capabilities.subscriptions.find(subscription=>subscription.adapterId===adapter.id&&subscription.workflow===node.workflow&&(subscription.nodeIds||[]).includes(node.id));const row=document.createElement('div');row.className='adapter-attachment';const label=document.createElement('label');label.className='checkbox-label';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=inherited||Boolean(direct);checkbox.disabled=inherited;checkbox.onchange=()=>changeNodeSubscription(adapter.id,node.workflow,node.id,checkbox.checked);label.append(checkbox,document.createTextNode((adapterMetadata(adapter.type)?.name||adapter.type)+' · '+adapter.id));row.append(label);if(inherited){const note=document.createElement('small');note.className='muted';note.textContent='Included by the workflow-wide subscription.';row.append(note)}else if(direct)row.append(subscriptionFilters(direct));section.append(row)}
 if(!capabilities.adapters.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='No adapters configured. Add a live monitor or Kafka adapter from the Adapters catalog.';section.append(empty)}
 const configure=makeButton('Configure adapters','events','quiet');configure.onclick=()=>openCapabilities(node.workflow);section.append(configure);return section;
}
function updateEventCounts(){for(const workflow of workflowTypes){const link=$('#lane-subscription-'+workflow);if(link){const inherited=capabilities.subscriptions.filter(subscription=>subscription.workflow===workflow&&!(subscription.nodeIds||[]).length);link.hidden=!inherited.length;link.title=inherited.length?'Workflow-wide event observers: '+[...new Set(inherited.map(subscription=>subscription.adapterId))].join(', '):'';link.replaceChildren();if(inherited.length){const line=subscriptionConnector();line.setAttribute('viewBox','0 0 64 12');line.setAttribute('preserveAspectRatio','none');line.querySelector('path').setAttribute('vector-effect','non-scaling-stroke');line.querySelector('path').setAttribute('d','M0 6 H64');link.append(line)}}const ids=new Set(capabilities.subscriptions.filter(subscription=>subscription.workflow===workflow).map(subscription=>subscription.adapterId));const button=$('#events-'+workflow);if(button){button.replaceChildren(icon('events'),document.createTextNode(ids.size?`Events · ${ids.size}`:'Events'))}}}
function addAdapterInstance(type){const metadata=adapterMetadata(type);if(!metadata){setCapabilityStatus('Adapter metadata is unavailable. Reload the catalog before adding it.','error');return null}if(metadata.available===false){setCapabilityStatus('This adapter is not available on the current backend.','error');return null}const adapter={id:type+'-'+crypto.randomUUID().slice(0,8),type,version:metadata.version||'1',config:defaultConfig({configurationSchema:metadata.configurationSchema||{}})};capabilities.adapters.push(adapter);selectedAdapterId=adapter.id;markDirty();return adapter}
function attachAdapterType(type,workflow,nodeId){let adapter=capabilities.adapters.find(instance=>instance.type===type),created=false;if(!adapter){adapter=addAdapterInstance(type);created=true}if(!adapter)return;if(nodeId)changeNodeSubscription(adapter.id,workflow,nodeId,true);else changeWorkflowSubscription(adapter.id,workflow,true);if(created)openCapabilities(workflow);status(`Attached ${adapterMetadata(type)?.name||type} to ${nodeId?'the selected node':workflowLabel(workflow)}. Processing edges are unchanged.`,'ok')}
function renderAdapterCatalog(){const root=$('#plugin-list'),query=$('#plugin-filter').value.toLowerCase();root.replaceChildren();for(const metadata of adapterCatalog.filter(adapter=>(adapter.type+' '+adapter.name+' '+adapter.description).toLowerCase().includes(query))){const card=document.createElement('article');card.className='plugin-option adapter-option';card.draggable=true;card.ondragstart=event=>event.dataTransfer.setData('application/x-plugintell-adapter',metadata.type);const heading=document.createElement('strong');heading.textContent=metadata.name;const description=document.createElement('small');description.className='muted';description.textContent=metadata.description||'Observes execution events independently from processing';const add=makeButton('Add to project','add','quiet');add.disabled=metadata.available===false;if(add.disabled)description.textContent+=' · Unavailable on this backend';add.onclick=()=>{if(addAdapterInstance(metadata.type)){render();openCapabilities()}};const identity=document.createElement('div');identity.className='catalog-option-heading';identity.append(heading,informationButton('adapter',metadata));card.append(icon('events'),identity,description,add);const selected=nodes.find(node=>node.id===selectedNodeId);if(selected){const attach=makeButton('Attach to selected node','connection','quiet');attach.onclick=()=>attachAdapterType(metadata.type,selected.workflow,selected.id);card.append(attach)}root.append(card)}if(!root.children.length){const empty=document.createElement('p');empty.className='empty-state';empty.textContent=adapterCatalog.length?'No adapters match this search.':'Adapter catalog is not available yet. Processing plugins remain available.';root.append(empty)}}
function setCapabilityStatus(message,kind='muted'){const status=$('#capability-status');status.textContent=message;status.className='inline-status '+kind}
function renderWorkflowSubscriptions(){const root=$('#workflow-subscriptions'),workflow=$('#capability-workflow').value||workflowTypes[0];root.replaceChildren();if(!nodes.some(node=>node.workflow===workflow)){const help=document.createElement('p');help.className='muted small-copy';help.textContent='Add processing nodes to this workflow before attaching an observer.';root.append(help)}for(const adapter of capabilities.adapters){const subscription=workflowSubscription(adapter.id,workflow),row=document.createElement('div');row.className='adapter-attachment';const label=document.createElement('label');label.className='checkbox-label';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=Boolean(subscription);checkbox.disabled=!nodes.some(node=>node.workflow===workflow);checkbox.onchange=()=>changeWorkflowSubscription(adapter.id,workflow,checkbox.checked);label.append(checkbox,document.createTextNode((adapterMetadata(adapter.type)?.name||adapter.type)+' · '+adapter.id));row.append(label);if(subscription)row.append(subscriptionFilters(subscription));else{const nodeScopes=capabilities.subscriptions.filter(item=>item.adapterId===adapter.id&&item.workflow===workflow&&(item.nodeIds||[]).length).reduce((count,item)=>count+item.nodeIds.length,0);if(nodeScopes){const note=document.createElement('small');note.className='muted';note.textContent=`Attached to ${nodeScopes} node scope(s). Select those nodes to edit their attachments.`;row.append(note)}}root.append(row)}if(!capabilities.adapters.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Add an adapter instance to subscribe to events.';root.append(empty)}}
function renderAdapterEditor(){const root=$('#adapter-editor'),adapter=capabilities.adapters.find(instance=>instance.id===selectedAdapterId);root.replaceChildren();if(!adapter)return;const metadata=adapterMetadata(adapter.type),heading=document.createElement('h4');heading.textContent=(metadata?.name||adapter.type)+' settings';heading.append(informationButton('adapter',metadata||{type:adapter.type,name:adapter.type,version:adapter.version,available:false}));const id=document.createElement('p');id.className='muted small-copy';id.textContent='Instance '+adapter.id+' · version '+adapter.version;root.append(heading,id);if(adapter.type==='ui'){const view=document.createElement('p');view.className='muted small-copy';view.textContent='View: '+(currentTemplateMetadata()?.name||capabilities.template.id);const choose=makeButton('Choose UI template','preview','quiet');choose.onclick=()=>{$('#capabilities-dialog').close();setStudioCatalog('templates')};root.append(view,choose)}if(metadata)root.append(createConfigForm({plugin:{id:adapter.type,configurationSchema:metadata.configurationSchema||{}},config:adapter.config},{},{onChange:markDirty}));else{const message=document.createElement('p');message.className='error';message.textContent='This adapter type is not installed. Its saved settings are preserved.';root.append(message)}const actions=document.createElement('div');actions.className='form-actions';const test=makeButton('Test adapter','check','secondary');test.disabled=!metadata;test.onclick=async()=>{test.disabled=true;setCapabilityStatus('Testing adapter configuration…');try{const result=await api(`/api/v1/adapters/${encodeURIComponent(adapter.type)}/test`,{method:'POST',body:JSON.stringify({config:adapter.config,...(adapter.type==='ui'?{template:capabilities.template}:{})})});setCapabilityStatus(result.message||JSON.stringify(result),result.success===false?'error':result.success===true?'ok':'muted')}catch(error){setCapabilityStatus(error.message,'error')}finally{test.disabled=!metadata}};const remove=makeButton('Remove adapter','trash','quiet danger');remove.onclick=()=>{capabilities.adapters=capabilities.adapters.filter(item=>item.id!==adapter.id);capabilities.subscriptions=capabilities.subscriptions.filter(item=>item.adapterId!==adapter.id);selectedAdapterId=null;markDirty();renderCapabilitiesDialog();render()};actions.append(test,remove);root.append(actions)}
function renderHostSettings(){const web=capabilities.host.type==='micronaut-web';$('#host-type').value=capabilities.host.type;$('#host-port').value=String(capabilities.host.port??8080);$('#host-open-browser').checked=Boolean(capabilities.host.openBrowser);$('#host-port-label').hidden=!web;$('#host-browser-label').hidden=!web;if(!web){$('#host-port').removeAttribute('aria-invalid');$('#host-port').setCustomValidity('')}$('#host-ui-help').textContent=!web&&capabilities.adapters.some(adapter=>adapter.type==='ui')?'Live monitors work in Studio. Choose the Micronaut web host when generating an application with a UI adapter.':web?'The generated application will expose its monitor on this HTTP port.':'The generated application runs from the command line.'}
function renderCapabilitiesDialog(){
 const type=$('#adapter-type'),previous=type.value;type.replaceChildren();for(const metadata of adapterCatalog)type.append(new Option(metadata.name,metadata.type));if(adapterCatalog.some(metadata=>metadata.type===previous))type.value=previous;$('#add-adapter').disabled=!adapterCatalog.length;
 const list=$('#adapter-instance-list');list.replaceChildren();for(const adapter of capabilities.adapters){const button=makeButton((adapterMetadata(adapter.type)?.name||adapter.type)+' · '+adapter.id,'events',selectedAdapterId===adapter.id?'secondary':'quiet');button.onclick=()=>{selectedAdapterId=adapter.id;renderCapabilitiesDialog()};const row=document.createElement('div');row.className='adapter-instance-info-row';row.append(button,informationButton('adapter',adapterMetadata(adapter.type)||{type:adapter.type,name:adapter.type,version:adapter.version,available:false}));list.append(row)}renderAdapterEditor();renderWorkflowSubscriptions();renderHostSettings();
 const templates=$('#monitor-template');templates.replaceChildren();const available=templateCatalog.length?templateCatalog:[{id:'standard',name:'Standard',version:'1'},{id:'water',name:'Water flow',version:'1'}];for(const template of available)templates.append(new Option(template.name,template.id));if(!available.some(template=>template.id===capabilities.template.id))templates.append(new Option('Unavailable: '+capabilities.template.id,capabilities.template.id));templates.value=capabilities.template.id;$('#template-settings').value=JSON.stringify(capabilities.template.settings||{},null,2);$('#template-settings').removeAttribute('aria-invalid');$('#template-settings').setCustomValidity('');$('#host-port').removeAttribute('aria-invalid');$('#host-port').setCustomValidity('');renderTemplateConfiguration();
}
function openCapabilities(workflow){if(workflow)$('#capability-workflow').value=workflow;renderCapabilitiesDialog();if(!$('#capabilities-dialog').open)$('#capabilities-dialog').showModal()}
function validateCapabilityInputs(){const invalid=$('#capabilities-dialog')?.querySelector('[aria-invalid="true"]');if(invalid){if(!$('#capabilities-dialog').open)$('#capabilities-dialog').showModal();invalid.focus();setCapabilityStatus('Correct the highlighted monitoring setting before saving.','error');return false}return true}
async function loadEventCatalogs(){try{const [adapters,templates]=await Promise.all([api('/api/v1/adapters'),api('/api/v1/templates')]);adapterCatalog=adapters;templateCatalog=templates;renderCapabilitiesDialog();if(catalogMode!=='processing')renderPlugins()}catch(error){setCapabilityStatus('Event capability catalog could not load: '+error.message,'error')}}
function openLiveMonitor(runId){if(!runId)return;if(accessToken)sessionStorage.setItem('plugintell.accessToken',accessToken);window.open('/ui/monitor.html?runId='+encodeURIComponent(runId),'_blank')}
function initializeEventCapabilities(){
 $('#open-capabilities').onclick=()=>openCapabilities();for(const workflow of workflowTypes)$('#events-'+workflow).onclick=()=>openCapabilities(workflow);$('#open-live-monitor').onclick=()=>openLiveMonitor(activeTraceId);
 $('#catalog-mode').onclick=event=>{const button=event.target.closest('[data-catalog]');if(button)setStudioCatalog(button.dataset.catalog)};
 $('#add-adapter').onclick=()=>{if(addAdapterInstance($('#adapter-type').value)){renderCapabilitiesDialog();render()}};$('#capability-workflow').onchange=renderWorkflowSubscriptions;
 $('#host-type').onchange=()=>{capabilities.host.type=$('#host-type').value;if(capabilities.host.type==='cli')capabilities.host.openBrowser=false;markDirty();renderHostSettings()};$('#host-port').oninput=()=>{const input=$('#host-port'),port=Number(input.value),valid=Number.isInteger(port)&&port>=1&&port<=65535;input.setAttribute('aria-invalid',String(!valid));input.setCustomValidity(valid?'':'Choose a port from 1 to 65535.');if(valid){capabilities.host.port=port;markDirty()}};$('#host-open-browser').onchange=()=>{capabilities.host.openBrowser=$('#host-open-browser').checked;markDirty()};
 $('#monitor-template').onchange=()=>{try{selectUiTemplate($('#monitor-template').value)}catch(error){setCapabilityStatus(error.message,'error')}};
 $('#template-settings').oninput=()=>{const input=$('#template-settings');try{const settings=JSON.parse(input.value||'{}');if(!settings||Array.isArray(settings)||typeof settings!=='object')throw Error('Template settings must be a JSON object.');if(Object.keys(settings).length>32||Object.values(settings).some(value=>!['string','number','boolean'].includes(typeof value)))throw Error('Use at most 32 simple string, number, or boolean settings.');validateTemplateSettingsClient(settings,currentTemplateMetadata());capabilities.template.settings=settings;renderTemplateConfiguration();input.removeAttribute('aria-invalid');input.setCustomValidity('');markDirty()}catch(error){input.setAttribute('aria-invalid','true');input.setCustomValidity(error.message);setCapabilityStatus(error.message,'error')}};
 $('#template-file').onchange=()=>$('#template-trust').checked=false;$('#import-template').onclick=async()=>{const file=$('#template-file').files?.[0];if(!file){setCapabilityStatus('Choose a template ZIP first.','error');return}const button=$('#import-template');button.disabled=true;try{const body=new FormData();body.append('file',file);const result=await api('/api/v1/templates/import?trustedExecutable='+String($('#template-trust').checked),{method:'POST',body});const template=result.template||result;await loadEventCatalogs();selectUiTemplate(template.id,true);markDirty();renderCapabilitiesDialog();$('#template-trust').checked=false;setCapabilityStatus('Imported '+(template.name||template.id)+'. Save and publish to use this pinned template.','ok')}catch(error){setCapabilityStatus(error.message,'error')}finally{button.disabled=false}};
 initializeUiTemplates();renderCapabilitiesDialog();hydrateIcons();loadEventCatalogs();
}
function initializeWorkbench(){
 hydrateIcons();
 for(const [id,key,values,fallback]of [['theme-choice','plugintell.theme',['system','light','dark'],'system'],['density-choice','plugintell.density',['comfortable','compact'],'comfortable']]){
  const select=$('#'+id);let value=fallback;try{const saved=localStorage.getItem(key);if(values.includes(saved))value=saved}catch{}select.value=value;document.documentElement.dataset[id==='theme-choice'?'theme':'density']=value;
  select.onchange=()=>{const next=values.includes(select.value)?select.value:fallback;document.documentElement.dataset[id==='theme-choice'?'theme':'density']=next;try{localStorage.setItem(key,next)}catch{}requestAnimationFrame(()=>workflowTypes.forEach(drawEdges))};
 }
 $('#open-connections').onclick=()=>$('#connections-dialog').showModal();$('#open-preview').onclick=()=>$('#preview-dialog').showModal();
 document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=()=>$('#'+button.dataset.closeDialog).close());
 $('#close-inspector').onclick=()=>setPanel('inspector',false);$('#close-catalog').onclick=()=>setPanel('catalog',false);
 $('#toggle-inspector').onclick=()=>setPanel('inspector',$('.workbench-shell').classList.contains('inspector-closed'));
 $('#toggle-catalog').onclick=()=>setPanel('catalog',$('.workbench-shell').classList.contains('catalog-closed'));
 $('#workspace-scrim').onclick=()=>{setPanel('inspector',false);if(window.innerWidth<=800||$('.workbench-shell').classList.contains('focus-mode'))setPanel('catalog',false)};
 $('#focus-mode').onclick=()=>{const main=$('.workbench-shell'),enabled=main.classList.toggle('focus-mode');$('#focus-mode').setAttribute('aria-pressed',String(enabled));setPanel('catalog',!enabled&&window.innerWidth>800);setPanel('inspector',!enabled&&window.innerWidth>1150);};
 $('#pipeline-name').oninput=markDirty;
 $('#arrange-nodes').onclick=()=>{for(const type of workflowTypes){const lane=nodes.filter(node=>node.workflow===type),columns=Math.max(1,Math.min(4,Math.floor(($('#canvas-'+type).clientWidth||700)/290)));lane.forEach((node,index)=>node.position={x:24+(index%columns)*290,y:28+Math.floor(index/columns)*laneRowSpacing(lane)})}persistLayout();render();status('Nodes arranged. Layout is stored locally; workflow connections are unchanged.','ok')};
 document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){if(document.querySelector('dialog[open]'))return;event.preventDefault();save()}if(event.key==='Escape'&&!document.querySelector('dialog[open]')){connectingNodeId=null;if(window.innerWidth<=1150||$('.workbench-shell').classList.contains('focus-mode')){setPanel('inspector',false);if(window.innerWidth<=800||$('.workbench-shell').classList.contains('focus-mode'))setPanel('catalog',false)}render()}});
 window.addEventListener('beforeunload',event=>{if(!dirty)return;event.preventDefault();event.returnValue=''});
 window.addEventListener('resize',()=>{updateScrim();requestAnimationFrame(()=>workflowTypes.forEach(drawEdges))});
 setPanel('catalog',window.innerWidth>800);setPanel('inspector',window.innerWidth>1150);render();$('#run-pipeline').onchange();
}
initializeWorkbench();
initializeEventCapabilities();
